const encoded='';
export function welcomeImage(){const chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';const out=[];let acc=0,bits=0;for(const c of encoded){if(c==='=')break;acc=(acc<<6)|chars.indexOf(c);bits+=6;if(bits>=8){bits-=8;out.push((acc>>bits)&255);}}return new Uint8Array(out);}
